SELECT value FROM
(
    SELECT value FROM {table}
    UNION ALL SELECT value FROM {table}
    UNION ALL SELECT value FROM {table}
    UNION ALL SELECT value FROM {table}
)
SETTINGS use_lz4_library_decompression = {decoder}
FORMAT Null

SELECT sum(cityHash64(value)) FROM
(
    SELECT value FROM {table}
    UNION ALL SELECT value FROM {table}
    UNION ALL SELECT value FROM {table}
    UNION ALL SELECT value FROM {table}
)
SETTINGS use_lz4_library_decompression = {decoder}
